     "code": "def process_command(command):\n    match command.split():\n        case [\"quit\" | \"exit\"]:\n            return \"Goodbye!\"\n        case [\"help\", topic]:\n            return f\"Help for: {topic}\"\n        case [\"search\", *keywords]:\n            return f\"Searching: {' '.join(keywords)}\"\n        case [\"set\", key, value]:\n            return f\"Setting {key} = {value}\"\n        case [\"get\", key]:\n            return f\"Getting {key}\"\n        case [cmd]:\n            return f\"Unknown command: {cmd}\"\n        case _:\n            return \"Invalid input\"\n\ncommands = [\"help login\", \"search python tutorial\", \"set theme dark\",\n            \"get name\", \"exit\", \"unknown\"]\nfor cmd in commands:\n    print(f\"  '{cmd}' -> {process_command(cmd)}\")\n\n# Structural pattern matching on data\ndef classify_shape(shape):\n    match shape:\n        case {\"type\": \"circle\", \"radius\": r}:\n            return f\"Circle with radius {r}\"\n        case {\"type\": \"rect\", \"w\": w, \"h\": h} if w == h:\n            return f\"Square with side {w}\"\n        case {\"type\": \"rect\", \"w\": w, \"h\": h}:\n            return f\"Rectangle {w}x{h}\"\n        case _:\n            return \"Unknown shape\"\n\nshapes = [{\"type\": \"circle\", \"radius\": 5}, {\"type\": \"rect\", \"w\": 4, \"h\": 4},\n          {\"type\": \"rect\", \"w\": 3, \"h\": 7}]\nfor s in shapes:\n    print(f\"  {classify_shape(s)}\")",
