     "code": "class Stream:\n    def __init__(self, iterable):\n        self._data = iter(iterable)\n    \n    def map(self, func):\n        return Stream(func(x) for x in self._data)\n    \n    def filter(self, pred):\n        return Stream(x for x in self._data if pred(x))\n    \n    def flat_map(self, func):\n        def gen():\n            for item in self._data:\n                yield from func(item)\n        return Stream(gen())\n    \n    def take(self, n):\n        import itertools\n        return Stream(itertools.islice(self._data, n))\n    \n    def reduce(self, func, initial=None):\n        from functools import reduce as _reduce\n        return _reduce(func, self._data) if initial is None else _reduce(func, self._data, initial)\n    \n    def group_by(self, key_func):\n        from collections import defaultdict\n        groups = defaultdict(list)\n        for item in self._data:\n            groups[key_func(item)].append(item)\n        return dict(groups)\n    \n    def collect(self):\n        return list(self._data)\n\nrecords = [\n    {\"name\": \"Alice\", \"dept\": \"Eng\", \"salary\": 90000},\n    {\"name\": \"Bob\", \"dept\": \"Eng\", \"salary\": 85000},\n    {\"name\": \"Charlie\", \"dept\": \"Sales\", \"salary\": 70000},\n    {\"name\": \"Diana\", \"dept\": \"Sales\", \"salary\": 75000},\n    {\"name\": \"Eve\", \"dept\": \"Eng\", \"salary\": 95000},\n]\n\n# Top 3 engineers by salary\ntop_eng = (Stream(records)\n    .filter(lambda r: r[\"dept\"] == \"Eng\")\n    .map(lambda r: {\"name\": r[\"name\"], \"salary\": r[\"salary\"]})\n    .collect())\ntop_eng.sort(key=lambda r: r[\"salary\"], reverse=True)\nprint(\"Top engineers:\", top_eng[:3])\n\n# Average salary by department\ngroups = Stream(records).group_by(lambda r: r[\"dept\"])\nfor dept, members in groups.items():\n    avg = sum(m[\"salary\"] for m in members) / len(members)\n    print(f\"  {dept}: avg ${avg:,.0f}\")",
