     "code": "class ValidationError:\n    def __init__(self, field, message):\n        self.field = field\n        self.message = message\n    def __repr__(self):\n        return f\"{self.field}: {self.message}\"\n\nclass Validator:\n    def __init__(self):\n        self.rules = {}\n    \n    def field(self, name):\n        self.rules[name] = FieldValidator(name)\n        return self.rules[name]\n    \n    def validate(self, data):\n        errors = []\n        for name, field_validator in self.rules.items():\n            value = data.get(name)\n            errors.extend(field_validator.check(value))\n        return errors\n\nclass FieldValidator:\n    def __init__(self, name):\n        self.name = name\n        self.checks = []\n    \n    def required(self):\n        self.checks.append((\"required\", lambda v: v is not None and v != \"\"))\n        return self\n    \n    def min_length(self, n):\n        self.checks.append((f\"min_length({n})\", lambda v, n=n: isinstance(v, str) and len(v) >= n))\n        return self\n    \n    def max_length(self, n):\n        self.checks.append((f\"max_length({n})\", lambda v, n=n: isinstance(v, str) and len(v) <= n))\n        return self\n    \n    def matches(self, pattern):\n        import re\n        self.checks.append((f\"matches({pattern})\", lambda v, p=pattern: bool(re.match(p, str(v)))))\n        return self\n    \n    def between(self, low, high):\n        self.checks.append((f\"between({low},{high})\", lambda v, l=low, h=high: l <= v <= h))\n        return self\n    \n    def check(self, value):\n        errors = []\n        for rule_name, check_func in self.checks:\n            try:\n                if not check_func(value):\n                    errors.append(ValidationError(self.name, f\"Failed {rule_name}\"))\n            except (TypeError, ValueError):\n                errors.append(ValidationError(self.name, f\"Failed {rule_name}\"))\n        return errors\n\nv = Validator()\nv.field(\"email\").required().matches(r\"^[\\w.]+@[\\w]+\\.[\\w]+$\")\nv.field(\"name\").required().min_length(2).max_length(50)\nv.field(\"age\").required().between(18, 120)\n\ntests = [\n    {\"email\": \"alice@test.com\", \"name\": \"Alice\", \"age\": 30},\n    {\"email\": \"bad\", \"name\": \"A\", \"age\": 200},\n    {\"email\": \"\", \"name\": \"\", \"age\": None},\n]\n\nfor data in tests:\n    errors = v.validate(data)\n    status = \"VALID\" if not errors else f\"INVALID: {errors}\"\n    print(f\"  {data} -> {status}\")",
