     "code": "def validate_schema(data, schema, path=\"root\"):\n    errors = []\n    \n    expected_type = schema.get(\"type\")\n    type_map = {\"string\": str, \"integer\": int, \"number\": (int, float),\n                \"boolean\": bool, \"array\": list, \"object\": dict, \"null\": type(None)}\n    \n    if expected_type and not isinstance(data, type_map.get(expected_type, object)):\n        errors.append(f\"{path}: expected {expected_type}, got {type(data).__name__}\")\n        return errors\n    \n    if expected_type == \"string\":\n        if \"minLength\" in schema and len(data) < schema[\"minLength\"]:\n            errors.append(f\"{path}: length {len(data)} < minLength {schema['minLength']}\")\n        if \"pattern\" in schema:\n            import re\n            if not re.match(schema[\"pattern\"], data):\n                errors.append(f\"{path}: doesn't match pattern {schema['pattern']}\")\n    \n    if expected_type in (\"integer\", \"number\"):\n        if \"minimum\" in schema and data < schema[\"minimum\"]:\n            errors.append(f\"{path}: {data} < minimum {schema['minimum']}\")\n        if \"maximum\" in schema and data > schema[\"maximum\"]:\n            errors.append(f\"{path}: {data} > maximum {schema['maximum']}\")\n    \n    if expected_type == \"array\":\n        if \"items\" in schema:\n            for i, item in enumerate(data):\n                errors.extend(validate_schema(item, schema[\"items\"], f\"{path}[{i}]\"))\n    \n    if expected_type == \"object\":\n        for prop, prop_schema in schema.get(\"properties\", {}).items():\n            if prop in data:\n                errors.extend(validate_schema(data[prop], prop_schema, f\"{path}.{prop}\"))\n            elif prop in schema.get(\"required\", []):\n                errors.append(f\"{path}.{prop}: required field missing\")\n    \n    return errors\n\nschema = {\n    \"type\": \"object\",\n    \"required\": [\"name\", \"age\", \"email\"],\n    \"properties\": {\n        \"name\": {\"type\": \"string\", \"minLength\": 2},\n        \"age\": {\"type\": \"integer\", \"minimum\": 0, \"maximum\": 150},\n        \"email\": {\"type\": \"string\", \"pattern\": r\"^[\\w.]+@[\\w]+\\.[\\w]+$\"},\n        \"tags\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}}\n    }\n}\n\ntests = [\n    {\"name\": \"Alice\", \"age\": 30, \"email\": \"alice@test.com\", \"tags\": [\"admin\"]},\n    {\"name\": \"B\", \"age\": -5, \"email\": \"bad\"},\n    {\"age\": \"thirty\"},\n]\n\nfor data in tests:\n    errors = validate_schema(data, schema)\n    print(f\"  {data}\")\n    print(f\"    -> {'VALID' if not errors else errors}\\n\")",
