     "t": "code",
     "lang": "python",
     "code": "class Observable:\n    def __init__(self, subscribe_func=None):\n        self._subscribe_func = subscribe_func\n        self._observers = []\n    \n    def subscribe(self, on_next, on_error=None, on_complete=None):\n        observer = {\"next\": on_next, \"error\": on_error or (lambda e: None),\n                     \"complete\": on_complete or (lambda: None)}\n        self._observers.append(observer)\n        if self._subscribe_func:\n            self._subscribe_func(observer)\n        return self\n    \n    def emit(self, value):\n        for obs in self._observers:\n            obs[\"next\"](value)\n    \n    def map(self, func):\n        parent = self\n        child = Observable()\n        parent.subscribe(lambda v: child.emit(func(v)))\n        return child\n    \n    def filter(self, pred):\n        parent = self\n        child = Observable()\n        parent.subscribe(lambda v: child.emit(v) if pred(v) else None)\n        return child\n    \n    def scan(self, func, seed):\n        parent = self\n        child = Observable()\n        acc = [seed]\n        def on_next(v):\n            acc[0] = func(acc[0], v)\n            child.emit(acc[0])\n        parent.subscribe(on_next)\n        return child\n    \n    def debounce(self, count):\n        parent = self\n        child = Observable()\n        buffer = []\n        def on_next(v):\n            buffer.append(v)\n            if len(buffer) >= count:\n                child.emit(list(buffer))\n                buffer.clear()\n        parent.subscribe(on_next)\n        return child\n\n# Temperature sensor stream\nsensor = Observable()\nsensor.filter(lambda t: t > 30).map(lambda t: f\"ALERT: {t}°C\").subscribe(\n    lambda msg: print(f\"  {msg}\"))\n\nsensor.scan(lambda acc, t: (acc[0]+t, acc[1]+1), (0, 0)).map(\n    lambda s: f\"  Running avg: {s[0]/s[1]:.1f}°C\").subscribe(print)\n\nfor temp in [25, 28, 32, 27, 35, 31, 29]:\n    print(f\"Sensor: {temp}°C\")\n    sensor.emit(temp)",
