     "t": "code",
     "lang": "python",
     "code": "import json\nfrom datetime import datetime, date\n\nclass Serializer:\n    _registry = {}\n    \n    @classmethod\n    def register(cls, type_name, serializer_func, deserializer_func):\n        cls._registry[type_name] = (serializer_func, deserializer_func)\n    \n    @classmethod\n    def serialize(cls, obj):\n        if isinstance(obj, dict):\n            return {k: cls.serialize(v) for k, v in obj.items()}\n        elif isinstance(obj, (list, tuple)):\n            return [cls.serialize(v) for v in obj]\n        elif isinstance(obj, set):\n            return {\"__type__\": \"set\", \"__data__\": [cls.serialize(v) for v in obj]}\n        \n        for type_name, (ser, _) in cls._registry.items():\n            if isinstance(obj, globals().get(type_name, type(None))) or type(obj).__name__ == type_name:\n                return {\"__type__\": type_name, \"__data__\": ser(obj)}\n        return obj\n    \n    @classmethod\n    def deserialize(cls, data):\n        if isinstance(data, dict):\n            if \"__type__\" in data:\n                type_name = data[\"__type__\"]\n                if type_name == \"set\":\n                    return set(cls.deserialize(v) for v in data[\"__data__\"])\n                if type_name in cls._registry:\n                    _, deser = cls._registry[type_name]\n                    return deser(data[\"__data__\"])\n            return {k: cls.deserialize(v) for k, v in data.items()}\n        elif isinstance(data, list):\n            return [cls.deserialize(v) for v in data]\n        return data\n\n# Register custom types\nSerializer.register(\"datetime\",\n    lambda d: d.isoformat(),\n    lambda s: datetime.fromisoformat(s))\n\nSerializer.register(\"date\",\n    lambda d: d.isoformat(),\n    lambda s: date.fromisoformat(s))\n\ndata = {\n    \"user\": \"Alice\",\n    \"created\": datetime(2024, 1, 15, 10, 30),\n    \"birthday\": date(1990, 5, 20),\n    \"tags\": {\"admin\", \"user\"},\n    \"scores\": [95, 87, 92]\n}\n\nserialized = Serializer.serialize(data)\njson_str = json.dumps(serialized, indent=2)\nprint(json_str)\n\nrestored = Serializer.deserialize(json.loads(json_str))\nprint(f\"\\nRestored: {restored}\")\nprint(f\"Type check: {type(restored['created'])}, {type(restored['tags'])}\")",
