     "t": "code",
     "lang": "python",
     "code": "class Token:\n    def __init__(self, type, value):\n        self.type = type\n        self.value = value\n    def __repr__(self):\n        return f\"Token({self.type}, {self.value})\"\n\ndef tokenize(expr):\n    tokens = []\n    i = 0\n    while i < len(expr):\n        if expr[i].isspace():\n            i += 1\n        elif expr[i].isdigit() or (expr[i] == '.' and i+1 < len(expr) and expr[i+1].isdigit()):\n            j = i\n            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):\n                j += 1\n            tokens.append(Token(\"NUM\", float(expr[i:j])))\n            i = j\n        elif expr[i] in \"+-*/()^\":\n            tokens.append(Token(\"OP\", expr[i]))\n            i += 1\n        else:\n            raise ValueError(f\"Unexpected character: {expr[i]}\")\n    return tokens\n\ndef parse_expression(tokens, pos=0):\n    left, pos = parse_term(tokens, pos)\n    while pos < len(tokens) and tokens[pos].value in \"+-\":\n        op = tokens[pos].value\n        right, pos = parse_term(tokens, pos + 1)\n        left = (op, left, right)\n    return left, pos\n\ndef parse_term(tokens, pos):\n    left, pos = parse_factor(tokens, pos)\n    while pos < len(tokens) and tokens[pos].value in \"*/\":\n        op = tokens[pos].value\n        right, pos = parse_factor(tokens, pos + 1)\n        left = (op, left, right)\n    return left, pos\n\ndef parse_factor(tokens, pos):\n    if tokens[pos].type == \"NUM\":\n        return tokens[pos].value, pos + 1\n    elif tokens[pos].value == \"(\":\n        result, pos = parse_expression(tokens, pos + 1)\n        return result, pos + 1  # skip ')'\n    elif tokens[pos].value == \"-\":\n        operand, pos = parse_factor(tokens, pos + 1)\n        return (\"neg\", operand), pos\n\ndef evaluate(tree):\n    if isinstance(tree, (int, float)):\n        return tree\n    op = tree[0]\n    if op == \"neg\":\n        return -evaluate(tree[1])\n    left, right = evaluate(tree[1]), evaluate(tree[2])\n    return {\"+\": left + right, \"-\": left - right,\n            \"*\": left * right, \"/\": left / right}[op]\n\nexpressions = [\"3 + 4 * 2\", \"(3 + 4) * 2\", \"10 / (5 - 3)\", \"2.5 * 4 + 1\"]\nfor expr in expressions:\n    tokens = tokenize(expr)\n    tree, _ = parse_expression(tokens)\n    result = evaluate(tree)\n    print(f\"  {expr} = {result}\")",
