     "code": "from datetime import datetime\n\nclass Event:\n    def __init__(self, type, data, timestamp=None):\n        self.type = type\n        self.data = data\n        self.timestamp = timestamp or datetime.now().isoformat()\n\nclass EventStore:\n    def __init__(self):\n        self.events = []\n    \n    def append(self, event):\n        self.events.append(event)\n    \n    def get_events(self, entity_id=None):\n        if entity_id:\n            return [e for e in self.events if e.data.get(\"id\") == entity_id]\n        return self.events\n\nclass BankAccount:\n    def __init__(self, account_id, event_store):\n        self.id = account_id\n        self.store = event_store\n        self.balance = 0\n        self.status = \"active\"\n    \n    def deposit(self, amount):\n        event = Event(\"deposited\", {\"id\": self.id, \"amount\": amount})\n        self.store.append(event)\n        self._apply(event)\n    \n    def withdraw(self, amount):\n        if amount > self.balance:\n            raise ValueError(\"Insufficient funds\")\n        event = Event(\"withdrawn\", {\"id\": self.id, \"amount\": amount})\n        self.store.append(event)\n        self._apply(event)\n    \n    def _apply(self, event):\n        if event.type == \"deposited\":\n            self.balance += event.data[\"amount\"]\n        elif event.type == \"withdrawn\":\n            self.balance -= event.data[\"amount\"]\n    \n    @classmethod\n    def replay(cls, account_id, event_store):\n        account = cls.__new__(cls)\n        account.id = account_id\n        account.store = event_store\n        account.balance = 0\n        account.status = \"active\"\n        for event in event_store.get_events(account_id):\n            account._apply(event)\n        return account\n\nstore = EventStore()\naccount = BankAccount(\"ACC-001\", store)\naccount.deposit(1000)\naccount.deposit(500)\naccount.withdraw(200)\nprint(f\"Balance: ${account.balance}\")\n\n# Replay from events\nreplayed = BankAccount.replay(\"ACC-001\", store)\nprint(f\"Replayed balance: ${replayed.balance}\")\n\n# Event log\nfor e in store.events:\n    print(f\"  {e.type}: {e.data}\")",
