     "code": "def compute_diff(old_lines, new_lines):\n    m, n = len(old_lines), len(new_lines)\n    dp = [[0] * (n + 1) for _ in range(m + 1)]\n    \n    for i in range(1, m + 1):\n        for j in range(1, n + 1):\n            if old_lines[i-1] == new_lines[j-1]:\n                dp[i][j] = dp[i-1][j-1] + 1\n            else:\n                dp[i][j] = max(dp[i-1][j], dp[i][j-1])\n    \n    diff = []\n    i, j = m, n\n    while i > 0 or j > 0:\n        if i > 0 and j > 0 and old_lines[i-1] == new_lines[j-1]:\n            diff.append((\" \", old_lines[i-1]))\n            i -= 1; j -= 1\n        elif j > 0 and (i == 0 or dp[i][j-1] >= dp[i-1][j]):\n            diff.append((\"+\", new_lines[j-1]))\n            j -= 1\n        else:\n            diff.append((\"-\", old_lines[i-1]))\n            i -= 1\n    \n    diff.reverse()\n    return diff\n\ndef apply_patch(original, diff):\n    result = []\n    for op, line in diff:\n        if op == \" \" or op == \"+\":\n            result.append(line)\n    return result\n\ndef format_diff(diff):\n    output = []\n    for op, line in diff:\n        prefix = {\"+\" : \"+ \", \"-\": \"- \", \" \": \"  \"}[op]\n        output.append(f\"{prefix}{line}\")\n    return \"\\n\".join(output)\n\nold = [\"def greet():\", \"    print('hello')\", \"\", \"greet()\"]\nnew = [\"def greet(name):\", \"    print(f'hello {name}')\", \"\", \"def main():\", \"    greet('world')\", \"\", \"main()\"]\n\ndiff = compute_diff(old, new)\nprint(\"Diff:\")\nprint(format_diff(diff))\n\npatched = apply_patch(old, diff)\nprint(f\"\\nPatched matches new: {patched == new}\")",
