     "code": "import heapq\nfrom collections import defaultdict\n\nclass WeightedGraph:\n    def __init__(self):\n        self.adj = defaultdict(list)\n    \n    def add_edge(self, u, v, weight):\n        self.adj[u].append((v, weight))\n        self.adj[v].append((u, weight))\n    \n    def dijkstra(self, start):\n        dist = {start: 0}\n        prev = {start: None}\n        pq = [(0, start)]\n        \n        while pq:\n            d, u = heapq.heappop(pq)\n            if d > dist.get(u, float('inf')):\n                continue\n            for v, w in self.adj[u]:\n                new_dist = d + w\n                if new_dist < dist.get(v, float('inf')):\n                    dist[v] = new_dist\n                    prev[v] = u\n                    heapq.heappush(pq, (new_dist, v))\n        \n        return dist, prev\n    \n    def shortest_path(self, start, end):\n        dist, prev = self.dijkstra(start)\n        if end not in prev:\n            return None, float('inf')\n        path = []\n        node = end\n        while node is not None:\n            path.append(node)\n            node = prev[node]\n        return path[::-1], dist[end]\n    \n    def mst_prim(self):\n        if not self.adj:\n            return []\n        start = next(iter(self.adj))\n        visited = {start}\n        edges = [(w, start, v) for v, w in self.adj[start]]\n        heapq.heapify(edges)\n        mst = []\n        \n        while edges and len(visited) < len(self.adj):\n            w, u, v = heapq.heappop(edges)\n            if v in visited:\n                continue\n            visited.add(v)\n            mst.append((u, v, w))\n            for next_v, next_w in self.adj[v]:\n                if next_v not in visited:\n                    heapq.heappush(edges, (next_w, v, next_v))\n        \n        return mst\n\ng = WeightedGraph()\nfor u, v, w in [(\"A\",\"B\",4), (\"A\",\"C\",2), (\"B\",\"C\",1), (\"B\",\"D\",5), (\"C\",\"D\",8), (\"C\",\"E\",10), (\"D\",\"E\",2)]:\n    g.add_edge(u, v, w)\n\npath, cost = g.shortest_path(\"A\", \"E\")\nprint(f\"Shortest A→E: {' → '.join(path)} (cost: {cost})\")\n\nmst = g.mst_prim()\nprint(f\"MST edges: {mst} (total: {sum(w for _,_,w in mst)})\")",
