     "t": "code",
     "lang": "python",
     "code": "import hashlib\nimport math\n\nclass BloomFilter:\n    def __init__(self, expected_items, false_positive_rate=0.01):\n        self.size = self._optimal_size(expected_items, false_positive_rate)\n        self.hash_count = self._optimal_hash_count(self.size, expected_items)\n        self.bit_array = [False] * self.size\n        self.count = 0\n    \n    def _optimal_size(self, n, p):\n        return int(-n * math.log(p) / (math.log(2) ** 2))\n    \n    def _optimal_hash_count(self, m, n):\n        return max(1, int(m / n * math.log(2)))\n    \n    def _hashes(self, item):\n        positions = []\n        for i in range(self.hash_count):\n            h = hashlib.md5(f\"{item}_{i}\".encode()).hexdigest()\n            positions.append(int(h, 16) % self.size)\n        return positions\n    \n    def add(self, item):\n        for pos in self._hashes(str(item)):\n            self.bit_array[pos] = True\n        self.count += 1\n    \n    def might_contain(self, item):\n        return all(self.bit_array[pos] for pos in self._hashes(str(item)))\n    \n    def stats(self):\n        filled = sum(self.bit_array)\n        return {\n            \"size\": self.size,\n            \"hash_functions\": self.hash_count,\n            \"items_added\": self.count,\n            \"bits_filled\": f\"{filled}/{self.size} ({filled/self.size*100:.1f}%)\"\n        }\n\nbf = BloomFilter(1000, 0.01)\nwords = [\"apple\", \"banana\", \"cherry\", \"date\", \"elderberry\", \"fig\", \"grape\"]\nfor word in words:\n    bf.add(word)\n\ntests = [\"apple\", \"banana\", \"mango\", \"kiwi\", \"cherry\", \"pear\"]\nfor word in tests:\n    result = \"probably yes\" if bf.might_contain(word) else \"definitely no\"\n    actual = word in words\n    print(f\"  '{word}': {result} (actually: {actual})\")\n\nprint(f\"\\nStats: {bf.stats()}\")",
